package cn.zhuatech.salesagent.service;import jakarta.validation.constraints.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class OutboundActionAuthorizationService{public Assessment assess(Request r){List<String>b=new ArrayList<>(),a=new ArrayList<>();if(!r.accountOwnerAssigned())b.add("客户账户责任人未指定");if(!r.contactPreferenceHonored())b.add("客户联系偏好未遵守");if(r.doNotContact())b.add("客户处于禁止联系名单");if(!r.customerDataUseApproved())b.add("客户数据使用未获批准");if(!r.commercialClaimsVerified())b.add("对外商业陈述未验证");if(r.discountOrCommitmentInvolved()&&!r.commercialApprovalComplete())b.add("折扣或承诺未获商业审批");if(r.highImpactAction()&&!r.humanApprovalComplete())b.add("高影响动作缺少人工批准");if(!r.auditTrailEnabled())b.add("Agent 对外动作审计未启用");if(!b.isEmpty()){a.add("阻断对外执行并转交销售负责人复核");return new Assessment(Decision.BLOCKED,b,a);}if(!r.rateLimitConfigured()||!r.cancelOrRollbackReady()){if(!r.rateLimitConfigured())a.add("配置客户级频率限制与防骚扰规则");if(!r.cancelOrRollbackReady())a.add("准备撤回消息、取消任务或纠正承诺流程");return new Assessment(Decision.REVIEW,b,a);}a.add("批准对外动作并记录输入、批准人、内容和结果");return new Assessment(Decision.EXECUTE,b,a);}public record Request(@NotBlank String actionId,boolean accountOwnerAssigned,boolean contactPreferenceHonored,boolean doNotContact,boolean customerDataUseApproved,boolean commercialClaimsVerified,boolean discountOrCommitmentInvolved,boolean commercialApprovalComplete,boolean highImpactAction,boolean humanApprovalComplete,boolean auditTrailEnabled,boolean rateLimitConfigured,boolean cancelOrRollbackReady){}public record Assessment(Decision decision,List<String>blockers,List<String>actions){}public enum Decision{EXECUTE,REVIEW,BLOCKED}}
